// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;
        integer j;
        reg [7:0] temp_data;

    // 1. DECLARE VARIABLES FIRST




    // 2. THEN WAIT for original tests
    wait(llm_go_signal == 1);

    // Initialize Checker Pointers (defined in test.v)
    // We must initialize them because we run before the original initial block
    wrp = 0;
    rdp = 0;

    // Initialize Inputs
    rst = 1;
    clr = 0;
    we = 0;
    re = 0;
    din = 8'h00;

    clr2 = 0;
    we2 = 0;
    re2 = 0;
    din2 = 8'h00;

    // Apply Reset (Active Low)
    #100;
    rst = 0;
    #200;
    rst = 1;
    #100;

    // ---------------------------------------------------------
    // SC FIFO TESTS (u0)
    // ---------------------------------------------------------
    $display("LLM: Starting SC FIFO Tests");

    // Test 1: Fill to Capacity (256) with Alternating Pattern
    // This targets bit-level mutations and full-flag logic
    for (i = 0; i < 256; i = i + 1) begin
        @(posedge clk);
        we = 1;
        din = (i[0]) ? 8'h55 : 8'hAA; // Alternating 01010101 / 10101010
        @(posedge clk);
        we = 0;
    end

    // Verify Full
    @(posedge clk);
    if (full !== 1'b1) $display("LLM FAIL: SC FIFO not full after 256 writes");

    // Test 2: Read to Empty
    // This targets empty-flag logic and pointer increments
    for (i = 0; i < 256; i = i + 1) begin
        @(posedge clk);
        while (empty) @(posedge clk); // Safety wait
        re = 1;
        @(posedge clk);
        re = 0;
    end

    // Verify Empty
    @(posedge clk);
    if (empty !== 1'b1) $display("LLM FAIL: SC FIFO not empty after 256 reads");

    // Test 3: Clear Functionality
    // Write 10 items
    for (i = 0; i < 10; i = i + 1) begin
        @(posedge clk);
        we = 1; din = i & 8'hFF;
        @(posedge clk);
        we = 0;
    end
    // Assert Clear
    @(posedge clk);
    clr = 1;
    @(posedge clk);
    clr = 0;

    // Sync Checker Pointers (Clear wipes FIFO but not checker buffer)
    // We must manually advance rdp to match wrp to avoid false errors in original TB
    rdp = wrp;

    // Check Empty
    @(posedge clk);
    if (empty !== 1'b1) $display("LLM FAIL: SC FIFO not empty after clear");

    // ---------------------------------------------------------
    // DC FIFO TESTS (u1)
    // ---------------------------------------------------------
    $display("LLM: Starting DC FIFO Tests");

    // Test 4: Fill DC FIFO (256) with Walking 1s
    // Targets Gray code conversion and synchronization logic
    for (i = 0; i < 256; i = i + 1) begin
        @(posedge wr_clk);
        we2 = 1;
        // Walking 1s pattern
        case (i % 8)
            0: din2 = 8'h01;
            1: din2 = 8'h02;
            2: din2 = 8'h04;
            3: din2 = 8'h08;
            4: din2 = 8'h10;
            5: din2 = 8'h20;
            6: din2 = 8'h40;
            7: din2 = 8'h80;
        endcase
        @(posedge wr_clk);
        we2 = 0;
    end

    // Verify Full (Allow sync time for CDC)
    repeat(10) @(posedge wr_clk);
    if (full2 !== 1'b1) $display("LLM FAIL: DC FIFO not full after 256 writes");

    // Test 5: Read DC FIFO
    for (i = 0; i < 256; i = i + 1) begin
        @(posedge rd_clk);
        while (empty2) @(posedge rd_clk);
        re2 = 1;
        @(posedge rd_clk);
        re2 = 0;
        repeat(2) @(posedge rd_clk); // Allow status update
    end

    // Verify Empty
    repeat(10) @(posedge rd_clk);
    if (empty2 !== 1'b1) $display("LLM FAIL: DC FIFO not empty after 256 reads");

    // Test 6: Interleaved Write/Read (Stress Test)
    // Write 50, Read 50 in chunks to stress pointer crossing
    for (j = 0; j < 5; j = j + 1) begin
        // Write 10
        for (i = 0; i < 10; i = i + 1) begin
            @(posedge wr_clk);
            we2 = 1; din2 = (j*10 + i) & 8'hFF;
            @(posedge wr_clk);
            we2 = 0;
        end
        // Read 10
        for (i = 0; i < 10; i = i + 1) begin
            @(posedge rd_clk);
            while (empty2) @(posedge rd_clk);
            re2 = 1;
            @(posedge rd_clk);
            re2 = 0;
            repeat(1) @(posedge rd_clk);
        end
    end

    // Test 7: Clear DC FIFO
    for (i = 0; i < 5; i = i + 1) begin
        @(posedge wr_clk);
        we2 = 1; din2 = 8'hFF;
        @(posedge wr_clk);
        we2 = 0;
    end
    @(posedge wr_clk);
    clr2 = 1;
    repeat(2) @(posedge wr_clk);
    clr2 = 0;

    // Sync Checker
    rdp = wrp;

    // Verify Empty
    repeat(10) @(posedge rd_clk);
    if (empty2 !== 1'b1) $display("LLM FAIL: DC FIFO not empty after clear");

    // 3. Handover
    $display("LLM Tests Finished. Handing over to Original TB...");
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #2000000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (f != 0) $fclose(f);
    $finish;
end

endmodule

